V.about=()=>`<div class="page-heading"><div><span class="eyebrow">THE STORY BEHIND THE STUDIO</span><h1>About VocabHub</h1><p class="sub">A focused space to build a stronger English vocabulary.</p></div></div><section class="creator-card"><div class="creator-photo-wrap">${photo('araf','Moshiur Rahman Araf — creator portrait')}</div><div class="creator-copy"><span class="eyebrow">FOUNDER & CREATOR</span><h2>${CREATOR.name}</h2><p class="creator-title">${CREATOR.title}</p><p>Created with a simple goal: make vocabulary learning more structured, engaging and memorable.</p><div class="creator-signature">CREATED BY MOSHIUR RAHMAN ARAF</div></div></section><section class="creator-card powered-card"><div class="creator-photo-wrap">${photo('shahed',PARTNER.by+' — portrait')}</div><div class="creator-copy"><span class="eyebrow">POWERED BY</span><img class="hub-logo-about" src="assets/hub-logo.png" alt="Shahed's English Hub logo"><h2>${PARTNER.hub}</h2><p class="powered-by-line">by <b>${PARTNER.by}</b></p><p>${PARTNER.dept}</p><div class="creator-signature">POWERED BY SHAHED'S ENGLISH HUB</div></div></section><section class="brand-showcase"><div class="brand-logo-large"><img src="assets/logo.png" alt="VocabHub logo"><div><strong>VocabHub</strong><small>YOUR PERSONAL VOCABULARY STUDIO</small></div></div><div><span class="eyebrow">OUR APPROACH</span><h2>Learn · Practise · Remember</h2><p class="sub">Five open difficulty levels, a shared game arena, smart revision and your own vocabulary library — built around the words already included in this edition.</p></div></section>`;

V.play=()=>{if(!S)return'<p>No session.</p>';if(S.fin){const a=T(S.mode)?S.att:S.n;return`<h1>Results</h1><div class="grid">${stat(S.c+' / '+a,'Correct')}${stat(a?Math.round(S.c/a*100)+'%':'–','Accuracy')}${stat('+'+S.xp,'XP')}${stat(Math.round((Date.now()-S.t0)/1000)+'s','Time')}${S.lad?stat(S.lad.peak,'Peak level'):''}${S.mode=='boss'?stat(S.lives>0?'Defeated':'Lost','Boss'):''}${S.rec&&S.rec.length?stat(S.rec.length,'Words recovered'):''}</div>${S.bad.length?`<h2>Review these</h2><div class="card">${[...new Set(S.bad)].map(w=>`<div>${esc(w.en)} — <span class="bn">${esc(w.bn)}</span></div>`).join('')}</div>`:''}${progressMini()}<div class="row"><button class="btn pri" onclick="start('${S.mode}',{n:${S.n0||S.n},dur:${S.dur||0}})">Play again</button><a class="btn" href="#history" style="text-decoration:none">Exam history</a><a class="btn" href="#${GAME_MODES.includes(S.mode)?'arcade':S.mode=='mistakes'?'mistakes':'practice'}" style="text-decoration:none">Back</a></div>`}
 if(S.mode=='mem')return memHTML();
 if(S.mode=='match'){return`<h1>Word Matching</h1><p class="sub">Tap an English word, then its meaning. ${S.done.size}/${S.ws.length}</p><div class="m"><div>${S.L.map((w,i)=>`<button class="btn opt ${S.done.has(w.id)?'dn':''} ${S.sel&&S.sel.id==w.id?'sel':''}" onclick="matchClick('L',${i})">${esc(w.en)}</button>`).join('')}</div><div>${S.R.map((w,i)=>`<button class="btn opt bn ${S.done.has(w.id)?'dn':''}" onclick="matchClick('R',${i})">${esc(short(w.bn))}</button>`).join('')}</div></div>`}
 if(S.mode=='flash'){const w=S.ws[S.i];return`<h1>Flashcard Recall</h1><p class="sub">${S.i+1} / ${S.ws.length}</p><div class="card"><div class="big">${esc(w.en)}</div>${S.rev?`<div class="big bn" style="font-size:24px">${esc(w.bn)}</div>${w.ex?'<p class="sub">'+esc(w.ex)+'</p>':''}<div class="row"><button class="btn pri" onclick="flashAns(1)">I know this</button><button class="btn" onclick="flashAns(0)">Need more practice</button></div>`:'<div class="row"><button class="btn pri" onclick="S.rev=1;render()">Reveal</button></div>'}</div>`}
 const q=S.qs[S.i];return`<h1>${T(S.mode)?(S.mode=='tf'?'True / False Blitz':'Speed Challenge')+' · <span id="tm">'+Math.max(0,Math.ceil((S.end-Date.now())/1000))+'s</span>':'Question '+(S.i+1)+' / '+(S.n||S.qs.length)}</h1><p class="sub">${esc(q.sub||'')} · ${S.c} correct${hudExtra()}</p>${!T(S.mode)?`<div class="bar"><i style="width:${S.i/(S.n||S.qs.length)*100}%"></i></div>`:''}<div class="card ${q.t=='tf'?'tf-card':''}"><div class="big ${q.bn?'bn':''} ${q.long?'long':''}">${esc(q.prompt)}</div>${q.letters?scrHTML(q):q.t=='hang'?hgHTML(q):q.opts?q.opts.map((o,i)=>`<button class="btn opt ${/[\u0980-\u09FF]/.test(o)?'bn':''}" onclick="pickOpt(${i})">${esc(o)}</button>`).join(''):`<div class="row"><input id="in" autocomplete="off" autofocus placeholder="Type your answer" onkeydown="if(event.key=='Enter')submitTyped()"><button class="btn pri" onclick="submitTyped()">Check</button><button class="btn" onclick="hint()">Hint</button></div><p class="sub" id="hint"></p>`}<div id="fb"></div></div>`};
const PAGES=[['dash','Dashboard','dash'],['levels','Levels','levels'],['lib','Library','lib'],['practice','Practice','practice'],['arcade','Arcade','arcade'],['revision','Revision','revision'],['mistakes','Mistakes','mistakes'],['missions','Missions','missions'],['achievements','Achievements','achievements'],['analytics','Analytics','analytics'],['history','History','history'],['profile','Profile','profile'],['settings','Settings','settings'],['admin','Word manager','admin'],['about','About VocabHub','about']];
