function topbar(v){const pg=PAGES.find(x=>x[0]===v)||PAGES[0],s=st();return`<header class="topbar"><div class="topbar-context"><span class="topbar-kicker"><img class="topbar-brand-icon" src="assets/logo.png" alt=""> VOCABHUB / LEARNING SPACE</span><b>${pg[1]}</b></div><div class="topbar-actions"><a class="hub-chip" href="#about" title="Powered by Shahed's English Hub"><img src="assets/hub-logo.png" alt="Shahed's English Hub"></a><span class="xp-chip">✦ ${s.xp} XP</span><button class="theme-toggle" onclick="cycleTheme()" aria-label="Change theme" title="Change theme"><span>${activeTheme()==='midnight'?'☾':'☼'}</span><small>${activeTheme()==='midnight'?'Dark':'Light'}</small></button></div></header>`}
