// Difficulty-aware wrapper: every game receives its own saved level selector.
const startUnfiltered=start;
start=function(mode,o={}){
 if(['mistakes','boss','daily','ladder'].includes(mode))return startSpecial(mode,o);
 clearInterval(S&&S.iv);S=null;
 const chosen=Number(o.level||D.gameLevels[mode]||3),pool=wordsAtLevel(chosen);
 if(pool.length<4){toast('এই Level-এ অন্তত ৪টি শব্দ দরকার। অন্য Level বেছে নাও।');return}
 const original=W;W=pool;
 try{startUnfiltered(mode,{...o,level:chosen});if(S)S.level=chosen;}finally{W=original;}
 if(['fill','syn','odd','sent'].includes(mode)&&!(S&&S.qs&&S.qs.length)){document.querySelectorAll('#toasts .toast').forEach(t=>t.remove());startUnfiltered(mode,{...o});if(S&&S.qs&&S.qs.length){S.level=0;toast('এই Level-এ এই গেমের জন্য উদাহরণ/সমার্থক শব্দ নেই — সব Level থেকে প্রশ্ন নেওয়া হয়েছে।')}}
};

